def compute(vars):
    operating_lease_obligations = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    ratio = operating_lease_obligations / total_obligations
    percentage = ratio * 100
    value = round(percentage)

    return {
        "value": value,
        "trace": {
            "operating_lease_obligations": operating_lease_obligations,
            "total_obligations": total_obligations,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
